function stableStringify(value) {
  if (value === null || typeof value !== 'object') return JSON.stringify(value);
  if (Array.isArray(value)) return '[' + value.map(stableStringify).join(',') + ']';
  return '{' + Object.keys(value).sort().map((key) => JSON.stringify(key) + ':' + stableStringify(value[key])).join(',') + '}';
}

function hash16(input) {
  let h1 = 0xdeadbeef ^ input.length;
  let h2 = 0x41c6ce57 ^ input.length;
  for (let i = 0; i < input.length; i++) {
    const ch = input.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return ((h2 >>> 0).toString(16).padStart(8, '0') + (h1 >>> 0).toString(16).padStart(8, '0')).slice(0, 16);
}

function hash32(input) {
  return hash16('a:' + input) + hash16('b:' + input);
}

function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function parseJsonIfString(value, fallback) {
  if (typeof value !== 'string') return value;
  try {
    return JSON.parse(value);
  } catch (error) {
    return fallback;
  }
}

function isSensitiveKey(key) {
  const k = String(key || '').toLowerCase();
  const compact = k.replace(/[^a-z0-9]/g, '');
  return k.includes('authorization') || k.includes('cookie') || k.includes('token') || k.includes('secret') || k.includes('password') || k.includes('credential') || k.includes('api-key') || k.includes('api_key') || compact.includes('apikey') || compact.includes('accesskey') || compact.includes('privatekey') || compact.includes('clientsecret');
}

function redactValue(value) {
  if (value === null || value === undefined) return value;
  if (Array.isArray(value)) return value.map(redactValue);
  if (typeof value !== 'object') return value;
  const result = {};
  for (const [rawKey, rawValue] of Object.entries(value)) {
    const key = String(rawKey || '').toLowerCase();
    result[key] = isSensitiveKey(key) ? '[REDACTED]' : redactValue(rawValue);
  }
  return result;
}

function normalizeStringArray(value, fallback) {
  value = parseJsonIfString(value, value);
  let refs = [];
  if (Array.isArray(value)) {
    refs = value.map((item) => {
      if (typeof item === 'string') return item.trim();
      if (isPlainObject(item)) return String(item.ref || item.id || item.name || '').trim();
      return '';
    }).filter(Boolean);
  } else if (typeof value === 'string' && value.trim()) {
    refs = value.split(',').map((item) => item.trim()).filter(Boolean);
  }
  if (refs.length === 0) refs = fallback;
  return Array.from(new Set(refs));
}

function normalizeRoleContextRef(value) {
  value = parseJsonIfString(value, value);
  if (Array.isArray(value) && value.length > 0) value = value[0];
  if (isPlainObject(value)) {
    const roleId = String(value.role_id || value.id || value.ref || '').trim();
    const version = String(value.role_context_version || value.version || 'v1').trim();
    if (roleId === 'PM_L3_DELIVERY_VALIDATION_OWNER' && version) {
      return { role_id: roleId, role_context_version: version };
    }
  }
  return { role_id: 'PM_L3_DELIVERY_VALIDATION_OWNER', role_context_version: 'v1' };
}

const input = $input.first().json || {};
const rawBody = isPlainObject(input.body) ? input.body : {};
const rawQuery = isPlainObject(input.query) ? input.query : {};
const rawHeaders = isPlainObject(input.headers) ? input.headers : {};
const headerMap = Object.fromEntries(Object.entries(rawHeaders).map(([key, value]) => [String(key).toLowerCase(), value]));
const body = redactValue(rawBody);
const query = redactValue(rawQuery);
const headers = redactValue(rawHeaders);
const repositoryFullName = rawBody.repository_full_name || rawQuery.repository_full_name || 'Viktoryyyyy/moex-robot';

if (repositoryFullName !== 'Viktoryyyyy/moex-robot') {
  throw new Error('Unsupported repository_full_name');
}

const clientIdempotencyKey = headerMap['idempotency-key'] || headerMap['x-idempotency-key'] || rawBody.idempotency_key || rawQuery.idempotency_key || '';
const idempotencySource = clientIdempotencyKey || stableStringify({
  project: 'MOEX Bot',
  route: 'Route B',
  spec_version: 'intake_role_task_adapter_v0.1',
  repository_full_name: repositoryFullName,
  body: rawBody,
  query: rawQuery
});
const idempotencyKey = String(clientIdempotencyKey || hash32(idempotencySource));
const runHash = hash32('workflow_run_id:' + idempotencyKey);
const workflowRunId = 'route_b_' + runHash;
const phaseRunId = 'phase_run_' + hash32('phase_run_id:' + workflowRunId);
const roleTaskId = 'role_task_' + hash32(phaseRunId + ':PM_L3_DELIVERY_VALIDATION_OWNER:1');
const targetBranchName = 'n8n/route-b-' + runHash.slice(0, 12);
const receivedAt = new Date().toISOString();

const defaultStaticContextRefs = [
  'MOEX_Bot_Target_Architecture_2026_All_In_One',
  'MOEX_Bot_Role_Context_Operating_Model_v1',
  'github_commit_flow_subchats_v3'
];
const staticContextRefs = normalizeStringArray(rawBody.static_context_refs || rawQuery.static_context_refs, defaultStaticContextRefs);
const roleContextRef = normalizeRoleContextRef(rawBody.role_context_ref || rawQuery.role_context_ref);
const schemaRefs = normalizeStringArray(rawBody.schema_refs || rawQuery.schema_refs || rawBody.required_schema_refs, [
  'pm_l2_to_pm_l3_request_envelope.v1',
  'pm_l3_to_subchat_task_package.v1',
  'subchat_to_pm_l3_return_package.v1',
  'pm_l3_to_pm_l2_validation_return_package.v1',
  'route_b_universal_role_runner.v0.1',
  'route_b_role_task_queue.v0.1',
  'route_b_pm_l3_decision_loop.v0.1',
  'route_b_universal_role_runner_db_contract.v0.1'
]);
const expectedOutputSchemaRef = 'route_b_pm_l3_decision_loop.v0.1';

const suppliedDynamicHandoff = parseJsonIfString(rawBody.dynamic_handoff || rawQuery.dynamic_handoff, null);
const dynamicHandoff = isPlainObject(suppliedDynamicHandoff) ? redactValue(suppliedDynamicHandoff) : {
  original_task: redactValue(rawBody.original_task || rawBody.root_task || rawBody.task || rawBody),
  execution_mode: rawBody.execution_mode || rawQuery.execution_mode || 'route_b_n8n_universal_role_runner',
  current_goal: rawBody.current_goal || rawBody.phase_goal || rawBody.goal || 'Route_B_Intake_To_Role_Task_Queue_Adapter_v0_1',
  approved_scope: rawBody.approved_scope || rawBody.approved_file_scope || [],
  not_in_scope: rawBody.not_in_scope || [],
  acceptance_criteria: rawBody.acceptance_criteria || []
};

const rootTaskJson = {
  workflow_name: 'MOEX_ROUTE_B_INTAKE_ACK_ROLE_TASK_ADAPTER_V0_1_TARGET',
  spec_version: 'intake_role_task_adapter_v0.1',
  workflow_run_id: workflowRunId,
  phase_run_id: phaseRunId,
  repository_full_name: repositoryFullName,
  target_branch_name: targetBranchName,
  idempotency_key: idempotencyKey,
  dynamic_handoff: dynamicHandoff,
  request: {
    query: query,
    body: body
  }
};

const taskPayloadJson = {
  role_id: 'PM_L3_DELIVERY_VALIDATION_OWNER',
  task_type: 'pm_l3_planning',
  workflow_run_id: workflowRunId,
  phase_run_id: phaseRunId,
  repository_full_name: repositoryFullName,
  target_branch_name: targetBranchName,
  idempotency_key: idempotencyKey,
  dynamic_handoff: dynamicHandoff,
  pm_l2_request_json: body.pm_l2_request_json || body,
  intake_adapter: {
    workflow_name: 'MOEX_ROUTE_B_INTAKE_ACK_ROLE_TASK_ADAPTER_V0_1_TARGET',
    received_at: receivedAt,
    initial_role_task_status: 'role_task_ready',
    expected_output_schema_ref: expectedOutputSchemaRef
  }
};

const contextRefsJson = {
  static_context_refs: staticContextRefs,
  role_context_ref: roleContextRef,
  schema_refs: schemaRefs
};

const intakePayload = {
  received_at: receivedAt,
  workflow_name: 'MOEX_ROUTE_B_INTAKE_ACK_ROLE_TASK_ADAPTER_V0_1_TARGET',
  spec_version: 'intake_role_task_adapter_v0.1',
  request: {
    headers: headers,
    query: query,
    body: body
  },
  controls: {
    async_dispatch: 'postgres_legacy_queue_plus_role_task_queue',
    execute_subworkflow_primary_dispatch: false,
    max_retries: 3,
    branch_source: 'deterministic_workflow_generated',
    initial_role_id: 'PM_L3_DELIVERY_VALIDATION_OWNER',
    initial_role_task_status: 'role_task_ready',
    expected_output_schema_ref: expectedOutputSchemaRef
  }
};

return [
  {
    json: {
      workflow_run_id: workflowRunId,
      phase_run_id: phaseRunId,
      role_task_id: roleTaskId,
      idempotency_key: idempotencyKey,
      repository_full_name: repositoryFullName,
      current_phase: 'intake_ack',
      target_branch_name: targetBranchName,
      status: 'queued',
      current_state: 'queued',
      max_retries: 3,
      event_type: 'intake_ack',
      event_payload_json: intakePayload,
      root_task_json: rootTaskJson,
      task_payload_json: taskPayloadJson,
      context_refs_json: contextRefsJson,
      expected_output_schema_ref: expectedOutputSchemaRef
    }
  }
];
